 * @param {HTMLElement} root - The #app container.
 * @returns {void}
 */
export function initAnimations(root) {
  const heroSvg = root.querySelector('#hero-svg');
  const speedSvg = root.querySelector('#speed-svg');
  if (!heroSvg || !speedSvg) return;

  // TODO: Implement atom orbit animation
  // TODO: Implement light particle trail animation
  console.log('[Animations] Initialized');
}

/**
 * Triggers a specific SVG animation sequence.
 * @param {AnimationTarget} target 
 * @returns {void}
 */
export function triggerAnimation(target) {
  console.log(`[Animations] Triggering: ${target}`);
}

/**
 * Initializes interactive controls for E=mc² and light speed demos.
 * @param {HTMLElement} root - The #app container.
 * @returns {void}
 */
export function initInteractions(root) {
  const massSlider = root.querySelector('#mass-slider');
  const massValue = root.querySelector('#mass-value');
  const energyDisplay = root.querySelector('#energy-display');
  const speedToggle = root.querySelector('#toggle-speed');

  if (!massSlider || !massValue || !energyDisplay) return;

  massSlider.addEventListener('input', (e) => {
    const mass = Number(e.target.value);
    massValue.textContent = mass;
    // E = mc^2
    const c = 299792458;
    const energy = mass * c * c;
    energyDisplay.textContent = `Energy: ${energy.toExponential(2)} J`;
  });

  if (speedToggle) {
    speedToggle.addEventListener('click', () => {
      // TODO: Toggle light speed visualization state
      console.log('[Interactions] Speed toggle clicked');
    });
  }
}

let audioCtx = null;

/**
 * Initializes the Web Audio API context. Must be called on user gesture.
 * @returns {Promise<void>}
 */
export async function initSounds() {
  if (audioCtx) return;
  audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  await audioCtx.resume();
  console.log('[Sounds] AudioContext initialized');
}

/**
 * Plays a procedural sci-fi sound effect.
 * @param {'click' | 'whoosh' | 'hum' | 'alarm'} type 
 * @returns {void}
 */
export function playSound(type) {
  if (!audioCtx) return;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.connect(gain);
  gain.connect(audioCtx.destination);

  const now = audioCtx.currentTime;
  switch (type) {
    case 'click':
      osc.frequency.setValueAtTime(800, now);
      osc.frequency.exponentialRampToValueAtTime(100, now + 0.1);
      gain.gain.setValueAtTime(0.3, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
      break;
    case 'whoosh':
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(200, now);
      osc.frequency.linearRampToValueAtTime(600, now + 0.3);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
      break;
    case 'hum':
      osc.type = 'sine';
      osc.frequency.setValueAtTime(60, now);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.linearRampToValueAtTime(0, now + 1.0);
      osc.start(now);
      osc.stop(now + 1.0);
      break;
    case 'alarm':
      osc.type = 'square';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.setValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.2, now);
      gain.gain.linearRampToValueAtTime(0, now + 0.4);
      osc.start(now);
      osc.stop(now + 0.4);
      break;
  }
}

import { initSounds, playSound } from './sounds.js';
import { initAnimations } from './animations.js';
import { initInteractions } from './interactions.js';

/**
 * Bootstraps the interactive physics website.
 * Initializes audio, animations, and interactions in dependency order.
 * @returns {void}
 */
export function initApp() {
  const app = document.getElementById('app');
  if (!app) {
    console.error('[App] #app container not found');
    return;
  }

  // Initialize sounds on first user gesture
  const unlockAudio = async () => {
    await initSounds();
    playSound('click');
    document.body.removeEventListener('click', unlockAudio);
  };
  document.body.addEventListener('click', unlockAudio, { once: true });

  // Initialize visual and interaction modules
  initAnimations(app);
  initInteractions(app);

  console.log('[App] Initialization complete');
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initApp);
} else {
  initApp();
}
